css:
.specimen {
  display: grid;
  gap: 10px;
  padding: 24px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 18px;
  color: #18181b;
}

.specimen p {
  margin: 0;
}

.w400 {
  font-weight: 400;
}

.w500 {
  font-weight: 500;
}

.w600 {
  font-weight: 600;
}

.w800 {
  font-weight: 800;
}

.serif {
  font-family: Georgia, "Times New Roman", serif;
}

.mono {
  font-family: ui-monospace, Consolas, "Courier New", monospace;
  font-size: 16px;
}
